        if (random() > 0.11) pixel(5, x, y, color);
      }
    }
    for (let x = 6; x <= 9; x += 1) pixel(5, x, 7, '#79542f');

    // 6 — Leaves (alpha cut-out)
    const leafColors = ['#3d7731', '#4b8c3b', '#589a45', '#32672c', '#62a54c'];
    for (let y = 0; y < 16; y += 1) {
