      pixel(9, i, 0, i % 4 === 0 ? '#e6fbff' : '#b9edf4');
      pixel(9, i, 15, i % 5 === 0 ? '#d7f7fc' : '#9ed9e4');
      pixel(9, 0, i, i % 4 === 0 ? '#e6fbff' : '#b9edf4');
      pixel(9, 15, i, i % 5 === 0 ? '#d7f7fc' : '#9ed9e4');
    }
    for (let i = 0; i < 6; i += 1) {
