  /* ------------------------------------------------------------------
   * Main loop
   * ------------------------------------------------------------------ */

  function animate() {
    requestAnimationFrame(animate);
    const dt = Math.min(clock.getDelta(), 0.05);
    elapsed += dt;

    if (state.started) {
      if (state.paused) {
        if (!state.menuOpen) state.paused = false;
      } else {
        updatePlayer(dt);
      }
      updatePlayerCamera(dt);
      updateHud(false);
      if (state.paused) clearTarget();
